def solve(rows):
    filtered_rows = [row for row in rows if row['status'] != 'cancelled']
    product_quantities = {}
    for row in filtered_rows:
        product = row['product']
        quantity = row['quantity']
        if product not in product_quantities:
            product_quantities[product] = []
        product_quantities[product].append(quantity)

    result = {}
    for product, quantities in product_quantities.items():
        quantities.sort()
        n = len(quantities)
        if n == 0:
            continue
        if n % 2 == 1:
            median = quantities[n // 2]
        else:
            median = (quantities[n // 2 - 1] + quantities[n // 2]) / 2
        result[product] = round(median, 1)
    return result
```

