def solve(rows):
    # Filter rows with state 'returned'
    returned_rows = [row for row in rows if row['state'] == 'returned']

    # Group by branch
    from collections import defaultdict
    branch_groups = defaultdict(list)
    for row in returned_rows:
        branch_groups[row['branch']].append(row)

    # Calculate count and group size for each branch
    branch_info = {}
    for branch, rows in branch_groups.items():
        count = len(rows)
        branch_info[branch] = (count, len(rows))

    # Calculate percentage for each branch
    branch_percentages = {}
    for branch, (count, group_size) in branch_info.items():
        if group_size == 0:
            continue
        percentage = round(100 * count / group_size, 1)
        branch_percentages[branch] = percentage

    # Filter branches with percentage >= 20
    result = []
    for branch, percentage in branch_percentages.items():
        if percentage >= 20:
            result.append((percentage, branch))

    # Sort by percentage descending, then value ascending
    result.sort(key=lambda x: (-x[0], x[1]))

    return result
